  INSERT INTO activities (id, creator_id, sport_id, title, description, level, level_max, max_participants, location_meeting, meeting_name, meeting_locality, location_objective, objective_name, starts_at, duration, visibility, requires_presence, status, distance_km, elevation_gain_m, is_demo, created_at) VALUES
    ('a0000000-0000-4000-a000-000000000042', 'd0000000-0000-4000-a000-000000000003', (SELECT id FROM sports WHERE key = 'climbing-sport'), 'Grimpe aux Vigneaux', 'Falaise ensoleillée au-dessus de la Durance, voies de 5 à 6b, idéale pour une demi-journée.', 'intermédiaire', NULL, 6, ST_SetSRID(ST_MakePoint(6.54, 44.825), 4326)::geography, 'Parking de la falaise', 'Les Vigneaux', NULL, NULL, now() + INTERVAL '60 days', INTERVAL '240 minutes', 'public', true, 'published', NULL, NULL, true, v_base),
    ('a0000000-0000-4000-a000-000000000043', 'd0000000-0000-4000-a000-00000000000d', (SELECT id FROM sports WHERE key = 'via-ferrata'), 'Via ferrata de la Croix de Toulouse', 'La classique au-dessus de Briançon, aérienne mais accessible, vue sur toute la ville.', 'intermédiaire', NULL, 6, ST_SetSRID(ST_MakePoint(6.64, 44.905), 4326)::geography, 'Départ de la via', 'Briançon', NULL, NULL, now() + INTERVAL '61 days', INTERVAL '180 minutes', 'public', true, 'published', NULL, NULL, true, v_base),
    ('a0000000-0000-4000-a000-000000000044', 'd0000000-0000-4000-a000-000000000006', (SELECT id FROM sports WHERE key = 'yoga'), 'Yoga au lever du soleil, Fort des Têtes', 'Séance douce sur l''esplanade du fort, face aux Écrins. Tapis à amener.', 'Tous niveaux', NULL, 8, ST_SetSRID(ST_MakePoint(6.652, 44.896), 4326)::geography, 'Esplanade du Fort des Têtes', 'Briançon', NULL, NULL, now() + INTERVAL '62 days', INTERVAL '75 minutes', 'public', true, 'published', NULL, NULL, true, v_base),
    ('a0000000-0000-4000-a000-000000000045', 'd0000000-0000-4000-a000-000000000002', (SELECT id FROM sports WHERE key = 'hiking'), 'Lacs de la haute Clarée', 'Montée tranquille vers les lacs avant la neige, pique-nique au bord de l''eau.', 'intermédiaire', NULL, 8, ST_SetSRID(ST_MakePoint(6.57, 45.06), 4326)::geography, 'Parking de Fontcouverte', 'Névache', ST_SetSRID(ST_MakePoint(6.53, 45.07), 4326)::geography, 'Lac des Cordes', now() + INTERVAL '63 days', INTERVAL '330 minutes', 'public', true, 'published', 13, 750, true, v_base),
    ('a0000000-0000-4000-a000-000000000046', 'd0000000-0000-4000-a000-000000000005', (SELECT id FROM sports WHERE key = 'paragliding'), 'Vol au-dessus de Briançon depuis Prorel', 'Déco de Prorel, conditions calmes le matin, atterro en ville.', 'intermédiaire', NULL, 4, ST_SetSRID(ST_MakePoint(6.635, 44.905), 4326)::geography, 'Télécabine du Prorel', 'Briançon', NULL, NULL, now() + INTERVAL '64 days', INTERVAL '180 minutes', 'public', true, 'published', NULL, NULL, true, v_base),
    ('a0000000-0000-4000-a000-000000000047', 'd0000000-0000-4000-a000-000000000007', (SELECT id FROM sports WHERE key = 'trail-running'), 'Trail des forts, de l''Infernet aux Têtes', 'Boucle technique entre les forts Vauban, belles relances et descentes raides.', 'avancé', NULL, 8, ST_SetSRID(ST_MakePoint(6.643, 44.898), 4326)::geography, 'Porte de Pignerol', 'Briançon', ST_SetSRID(ST_MakePoint(6.67, 44.91), 4326)::geography, 'Fort de l''Infernet', now() + INTERVAL '65 days', INTERVAL '150 minutes', 'public', true, 'published', 14, 950, true, v_base),
