    ('a0000000-0000-4000-a000-000000000049', 'd0000000-0000-4000-a000-00000000000e', (SELECT id FROM sports WHERE key = 'climbing-multipitch'), 'Grande voie à Freissinières', 'Voie ensoleillée de 6 longueurs, 6a max, rappels sur la voie.', 'avancé', NULL, 3, ST_SetSRID(ST_MakePoint(6.539, 44.754), 4326)::geography, 'Parking de Pallon', 'Freissinières', NULL, NULL, now() + INTERVAL '67 days', INTERVAL '360 minutes', 'public', true, 'published', NULL, NULL, true, v_base),
    ('a0000000-0000-4000-a000-00000000004a', 'd0000000-0000-4000-a000-000000000014', (SELECT id FROM sports WHERE key = 'mtb-enduro'), 'Enduro de Montgenèvre', 'Trois descentes en forêt de mélèzes, remontées à pied ou en navette perso.', 'avancé', NULL, 6, ST_SetSRID(ST_MakePoint(6.723, 44.931), 4326)::geography, 'Office de tourisme', 'Montgenèvre', NULL, NULL, now() + INTERVAL '68 days', INTERVAL '240 minutes', 'public', true, 'published', NULL, NULL, true, v_base),
