-- ============================================================================
-- 00465 — Demo mode : 25 sorties dans le Briançonnais (Scott 2026-10-21 :
-- « voir comment ça donne quand un endroit est rempli d'activités »).
-- De Montgenèvre à Guillestre : Briançon, Clarée, Cervières, Vigneaux,
-- Freissinières, Fournel, Ailefroide, Mont-Dauphin. a0000000-…42→5a.
-- Créateurs et membres = démo existants (créateur toujours inscrit), chat,
-- matériel et covoiturage comme 00457/00462. Puis séquence de created_at
-- réécrite pour TOUTES les sorties démo (piège n°5 : created_at partagé) avec
-- les nouvelles réparties uniformément, et calendrier deux-par-jour ré-appliqué.
-- ============================================================================
DO $$
DECLARE v_base TIMESTAMPTZ;
BEGIN
  PERFORM set_config('junto.bypass_lock', 'true', true);
  PERFORM set_config('junto.skip_message_push', 'true', true);
  SELECT min(created_at) INTO v_base FROM activities WHERE is_demo AND id::text LIKE 'a0000000-%';

  ON CONFLICT (id) DO NOTHING;

  ) AS x(a, u) ON CONFLICT DO NOTHING;

  UPDATE participations SET transport_type = 'car', transport_seats = 4, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000043') - INTERVAL '30 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000043' AND user_id = 'd0000000-0000-4000-a000-000000000006';
  UPDATE participations SET transport_type = 'car', transport_seats = 3, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000043') - INTERVAL '60 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000043' AND user_id = 'd0000000-0000-4000-a000-00000000000d';
  UPDATE participations SET transport_type = 'car', transport_seats = 4, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000045') - INTERVAL '45 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000045' AND user_id = 'd0000000-0000-4000-a000-000000000003';
  UPDATE participations SET transport_type = 'car', transport_seats = 3, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000045') - INTERVAL '45 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000045' AND user_id = 'd0000000-0000-4000-a000-000000000002';
  UPDATE participations SET transport_type = 'car', transport_seats = 4, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000046') - INTERVAL '60 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000046' AND user_id = 'd0000000-0000-4000-a000-000000000006';
  UPDATE participations SET transport_type = 'on_foot' WHERE activity_id = 'a0000000-0000-4000-a000-000000000046' AND user_id = 'd0000000-0000-4000-a000-000000000008';
  UPDATE participations SET transport_type = 'car', transport_seats = 3, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000047') - INTERVAL '45 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000047' AND user_id = 'd0000000-0000-4000-a000-000000000005';
  UPDATE participations SET transport_type = 'public_transport' WHERE activity_id = 'a0000000-0000-4000-a000-000000000047' AND user_id = 'd0000000-0000-4000-a000-000000000007';
  UPDATE participations SET transport_type = 'public_transport' WHERE activity_id = 'a0000000-0000-4000-a000-000000000047' AND user_id = 'd0000000-0000-4000-a000-000000000014';
  UPDATE participations SET transport_type = 'car', transport_seats = 3, transport_from_name = 'Guillestre', transport_from_lng = 6.65, transport_from_lat = 44.66, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000048') - INTERVAL '60 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000048' AND user_id = 'd0000000-0000-4000-a000-00000000000e';
  UPDATE participations SET transport_type = 'car', transport_seats = 4, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000048') - INTERVAL '30 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000048' AND user_id = 'd0000000-0000-4000-a000-000000000002';
  UPDATE participations SET transport_type = 'car', transport_seats = 2, transport_from_name = 'Guillestre', transport_from_lng = 6.65, transport_from_lat = 44.66, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000049') - INTERVAL '30 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000049' AND user_id = 'd0000000-0000-4000-a000-00000000000e';
  UPDATE participations SET transport_type = 'car', transport_seats = 4, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-00000000004a') - INTERVAL '45 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-00000000004a' AND user_id = 'd0000000-0000-4000-a000-00000000000d';
  UPDATE participations SET transport_type = 'bike' WHERE activity_id = 'a0000000-0000-4000-a000-00000000004a' AND user_id = 'd0000000-0000-4000-a000-000000000008';
  UPDATE participations SET transport_type = 'on_foot' WHERE activity_id = 'a0000000-0000-4000-a000-00000000004a' AND user_id = 'd0000000-0000-4000-a000-000000000014';
  UPDATE participations SET transport_type = 'car', transport_seats = 2, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-00000000004b') - INTERVAL '30 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-00000000004b' AND user_id = 'd0000000-0000-4000-a000-00000000000d';
  UPDATE participations SET transport_type = 'bike' WHERE activity_id = 'a0000000-0000-4000-a000-00000000004b' AND user_id = 'd0000000-0000-4000-a000-000000000002';
  UPDATE participations SET transport_type = 'car', transport_seats = 4, transport_from_name = 'Guillestre', transport_from_lng = 6.65, transport_from_lat = 44.66, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-00000000004e') - INTERVAL '60 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-00000000004e' AND user_id = 'd0000000-0000-4000-a000-00000000000e';
  UPDATE participations SET transport_type = 'car', transport_seats = 4, transport_from_name = 'Guillestre', transport_from_lng = 6.65, transport_from_lat = 44.66, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-00000000004e') - INTERVAL '45 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-00000000004e' AND user_id = 'd0000000-0000-4000-a000-00000000000c';
  UPDATE participations SET transport_type = 'car', transport_seats = 2, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-00000000004f') - INTERVAL '60 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-00000000004f' AND user_id = 'd0000000-0000-4000-a000-000000000007';
  UPDATE participations SET transport_type = 'car', transport_seats = 3, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000050') - INTERVAL '30 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000050' AND user_id = 'd0000000-0000-4000-a000-000000000006';
  UPDATE participations SET transport_type = 'car', transport_seats = 3, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000050') - INTERVAL '30 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000050' AND user_id = 'd0000000-0000-4000-a000-000000000008';
  UPDATE participations SET transport_type = 'car', transport_seats = 4, transport_from_name = 'Vars', transport_from_lng = 6.684, transport_from_lat = 44.573, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000051') - INTERVAL '60 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000051' AND user_id = 'd0000000-0000-4000-a000-000000000014';
  UPDATE participations SET transport_type = 'car', transport_seats = 3, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000053') - INTERVAL '30 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000053' AND user_id = 'd0000000-0000-4000-a000-000000000002';
  UPDATE participations SET transport_type = 'car', transport_seats = 4, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000053') - INTERVAL '60 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000053' AND user_id = 'd0000000-0000-4000-a000-000000000005';
  UPDATE participations SET transport_type = 'car', transport_seats = 3, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000055') - INTERVAL '30 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000055' AND user_id = 'd0000000-0000-4000-a000-000000000007';
  UPDATE participations SET transport_type = 'car', transport_seats = 2, transport_from_name = 'Briançon', transport_from_lng = 6.635, transport_from_lat = 44.897, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000056') - INTERVAL '60 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000056' AND user_id = 'd0000000-0000-4000-a000-000000000003';
  UPDATE participations SET transport_type = 'on_foot' WHERE activity_id = 'a0000000-0000-4000-a000-000000000056' AND user_id = 'd0000000-0000-4000-a000-000000000008';
  UPDATE participations SET transport_type = 'car', transport_seats = 2, transport_from_name = 'Guillestre', transport_from_lng = 6.65, transport_from_lat = 44.66, transport_departs_at = (SELECT starts_at FROM activities WHERE id = 'a0000000-0000-4000-a000-000000000059') - INTERVAL '45 minutes' WHERE activity_id = 'a0000000-0000-4000-a000-000000000059' AND user_id = 'd0000000-0000-4000-a000-00000000000e';
  UPDATE participations SET transport_type = 'on_foot' WHERE activity_id = 'a0000000-0000-4000-a000-000000000059' AND user_id = 'd0000000-0000-4000-a000-000000000006';
  UPDATE conversations c SET last_message_at = m.last_at FROM (SELECT conversation_id, max(created_at) AS last_at FROM messages GROUP BY conversation_id) m WHERE m.conversation_id = c.id AND c.type = 'activity' AND c.activity_id IN ('a0000000-0000-4000-a000-000000000042', 'a0000000-0000-4000-a000-000000000043', 'a0000000-0000-4000-a000-000000000044', 'a0000000-0000-4000-a000-000000000045', 'a0000000-0000-4000-a000-000000000046', 'a0000000-0000-4000-a000-000000000047', 'a0000000-0000-4000-a000-000000000048', 'a0000000-0000-4000-a000-000000000049', 'a0000000-0000-4000-a000-00000000004a', 'a0000000-0000-4000-a000-00000000004b', 'a0000000-0000-4000-a000-00000000004c', 'a0000000-0000-4000-a000-00000000004d', 'a0000000-0000-4000-a000-00000000004e', 'a0000000-0000-4000-a000-00000000004f', 'a0000000-0000-4000-a000-000000000050', 'a0000000-0000-4000-a000-000000000051', 'a0000000-0000-4000-a000-000000000052', 'a0000000-0000-4000-a000-000000000053', 'a0000000-0000-4000-a000-000000000054', 'a0000000-0000-4000-a000-000000000055', 'a0000000-0000-4000-a000-000000000056', 'a0000000-0000-4000-a000-000000000057', 'a0000000-0000-4000-a000-000000000058', 'a0000000-0000-4000-a000-000000000059', 'a0000000-0000-4000-a000-00000000005a');

  -- Séquence propre : les 25 nouvelles réparties uniformément parmi les existantes.
  WITH existing AS (
    SELECT id, row_number() OVER (ORDER BY created_at, id) AS rn, count(*) OVER () AS n
    FROM activities WHERE is_demo AND deleted_at IS NULL AND id::text LIKE 'a0000000-%'
      AND id::text NOT BETWEEN 'a0000000-0000-4000-a000-000000000042' AND 'a0000000-0000-4000-a000-00000000005a'
  ),
  fresh AS (
    SELECT id, row_number() OVER (ORDER BY id) AS k, count(*) OVER () AS n
    FROM activities WHERE id::text BETWEEN 'a0000000-0000-4000-a000-000000000042' AND 'a0000000-0000-4000-a000-00000000005a'
  ),
  keyed AS (
    SELECT id, rn::numeric / n AS key FROM existing
    UNION ALL SELECT id, (k - 0.5)::numeric / n FROM fresh
  ),
  seq AS (SELECT id, row_number() OVER (ORDER BY key, id) AS r FROM keyed)
  UPDATE activities a SET created_at = v_base + make_interval(mins => s.r::int)
  FROM seq s WHERE a.id = s.id;

  WITH ordered AS (
    SELECT id, row_number() OVER (ORDER BY created_at, id) AS rn
    FROM activities
    WHERE is_demo = true AND deleted_at IS NULL AND id::text NOT LIKE 'c0000000-%'
  ),
  target AS (
    SELECT a.id, a.starts_at AS old_start,
           date_trunc('day', now())
             + make_interval(
                 days  => (1 + ((o.rn - 1) / 2))::int,
                 hours => (ARRAY[9,14,8,16,10,17,11,15])[((o.rn - 1) % 8) + 1],
                 mins  => (ARRAY[0,30,15,0,45,30,0,30])[((o.rn - 1) % 8) + 1]
               ) AS new_start
    FROM activities a JOIN ordered o ON o.id = a.id
  ),
  shifted_transport AS (
    UPDATE participations p
    SET transport_departs_at = p.transport_departs_at + (t.new_start - t.old_start)
    FROM target t
    WHERE p.activity_id = t.id AND p.transport_departs_at IS NOT NULL
    RETURNING p.id
  ),
  shifted_pickups AS (
    UPDATE seat_requests s
    SET requested_pickup_at = s.requested_pickup_at + (t.new_start - t.old_start)
    FROM target t
    WHERE s.activity_id = t.id AND s.requested_pickup_at IS NOT NULL
    RETURNING s.id
  )
  UPDATE activities a
  SET starts_at = t.new_start, status = 'published'
  FROM target t
  WHERE a.id = t.id;
END $$;
